"""Connected source health assignment, bounds and HUD/icon phase."""
import os
import subprocess
import tempfile
import unittest
from pathlib import Path
from haxe_test_support import HAXE_COMMAND
from source_bar_fixture_support import bar_fixture_files
from test_nv_multifield_routes import method
ROOT=Path(__file__).resolve().parents[2]

def actual_bounds(files):
 files['flixel/util/helpers/FlxBounds.hx']=(ROOT/'.haxelib/flixel/6,1,2/flixel/util/helpers/FlxBounds.hx').read_text()
 files['flixel/util/FlxStringUtil.hx']='package flixel.util;class FlxStringUtil {public static function getDebugString(v:Dynamic):String return "bounds";}class LabelValuePair {public static function weak(k:String,v:Dynamic):Dynamic return {label:k,value:v};}'

class SourceHealthIntegrationTest(unittest.TestCase):
 def test_actual_setter_and_source_phase_donor_guards_and_reentry(self):
  ps=(ROOT/'source/PlayState.hx').read_text()
  methods='\n'.join(method(ps,m).replace('function ','public function ',1) for m in ['function set_health(','function updateSourceHealthLimit(','function updateSourceHUDHealthPhase('])
  files=bar_fixture_files();actual_bounds(files)
  files['NightmareVisionHealthIcon.hx']='typedef NightmareVisionHealthIcon = Main.Icon;'
  icon=method((ROOT/'source/HealthIcon.hx').read_text(),'public inline function updateIconAnim(')
  icon=icon.replace('{','{if (frameProbe != null) frameProbe(health);',1)
  files['Main.hx']=r'''import flixel.math.FlxMath;import flixel.FlxSprite;import flixel.util.helpers.FlxBounds;
class Conductor {public static var songPosition:Float=0;}
class Controller {public var frameIndex=0;public var curAnim={curFrame:0};public function new(){}}
class Icon extends FlxSprite {public var updateFrames=true;public var frameProbe:Float->Void;public var autoUpdate=false;public function new(){super();animation=new Controller();}__ICON__}
class HealthHost {public var mode:Int;public var sourceHUDIconMode=0;function updatePsychSourceIcons(e:Float):Void{}public var psychSourceIconP1(get,never):Dynamic;function get_psychSourceIconP1():Dynamic return iconP1;public var psychSourceIconP2(get,never):Dynamic;function get_psychSourceIconP2():Dynamic return iconP2;public var health(default,set):Float=1;public var iconsAnimations=true;public var sourceHUDBarMode=1;public var healthBounds=new FlxBounds<Float>(0,2);public var psychSourceHealthBar:PsychSourceBar;public var playHUD:NightmareVisionHUDAdapter;public var iconP1=new Icon();public var iconP2=new Icon();public var calls=0;public var observed:Float=0;public var syncValues:Array<Float>=[];public var songLength:Float=2000;public var phases:Array<String>=[];public var songPositionBar(default,set):Float=0;function set_songPositionBar(v:Float):Float {if(phases!=null)phases.push("timer");return songPositionBar=v;}public var startingSong=false;public var paused=false;public var endingSong=false;public var SONG={song:"fixture"};public var nightmareVisionPrefs={view:{noteOffset:0.,timeBarType:"Time Left"}};public var nvBar:NightmareVisionBar;public var timeBar:NightmareVisionBar;public function new(m:Int){mode=m;var o:SourceBarOwner={image:Paths.image,antialiasing:()->true};psychSourceHealthBar=new PsychSourceBar(0,0,"health",()->{calls++;observed=health;return health;},0,2,o);if(m==2){nvBar=new NightmareVisionBar(0,0,"health",()->{calls++;observed=health;return health;},0,2,o);timeBar=new NightmareVisionBar(0,0,"time",()->songPositionBar,0,1,o);playHUD=new NightmareVisionHUDAdapter({parent:this,healthFill:nvBar,healthBackground:nvBar.bg,sourceHealthBar:nvBar,sourceTimeBar:timeBar,iconP1:iconP1,iconP2:iconP2,scoreText:new FlxSprite(),songFill:timeBar,songBackground:timeBar.bg,timeText:{text:"",visible:true,alpha:1.},showTime:true});}}function sourceNoteTimingMode()return mode;function setAllHaxeVar(name:String,v:Dynamic):Void syncValues.push(v);public function sampleBar():Void{if(mode==2)nvBar.update(.016);else psychSourceHealthBar.update(.016);}__METHODS__}
class Main {static function ok(v:Bool,m:String):Void if(!v)throw m;static function near(a:Float,b:Float,m:String):Void if(Math.abs(a-b)>.00000001)throw m+":"+a+" vs"+b;static function main(){for(mode in [1,2]){var h=new HealthHost(mode);h.health=3.123456789;near(h.health,mode==1?3.12346:3.123456789,"round/raw no settercap");near(h.observed,h.health,"store before callback");ok(h.calls==1,"single current HUD/valuefunction");h.health=3.123456789;ok(h.calls==2,"equality callback");h.health=-.25;near(h.health,-.25,"source belowmin preserved");if(mode==1){h.iconsAnimations=false;var before=h.calls;h.health=.6;ok(h.calls==before,"icon flag setterguard");h.iconsAnimations=true;h.psychSourceHealthBar.enabled=false;h.health=.7;ok(h.calls==before,"disabled setterguard");h.psychSourceHealthBar.enabled=true;h.psychSourceHealthBar.valueFunction=null;h.health=.8;near(h.health,.8,"nullfn stores withoutsample");var original=h.psychSourceHealthBar;h.psychSourceHealthBar=null;h.health=.9;near(h.health,.9,"nullbar setterguard");var threw=false;try h.updateSourceHealthLimit()catch(_:Dynamic)threw=true;ok(threw,"installednullbar update sourcefailure");h.sourceHUDBarMode=0;h.updateSourceHealthLimit();h.sourceHUDBarMode=1;h.psychSourceHealthBar=original;h.psychSourceHealthBar.valueFunction=()->h.health;}else{h.nvBar.enabled=false;var before=h.calls;h.health=.7;ok(h.calls==before+1,"NV callback independentenabled");h.nvBar.enabled=true;h.nvBar.valueFunction=null;var threw=false;try h.health=.8 catch(_:Dynamic)threw=true;ok(threw&&h.health==.8,"NV null callbackerror afterstore");h.nvBar.valueFunction=()->h.health;}for(v in [.39998,.4,1.6,1.60002]){h.health=v;var p=mode==1?h.psychSourceHealthBar.percent:h.nvBar.percent;if(mode==1){ok(h.iconP1.animation.curAnim.curFrame==(p<20?1:0)&&h.iconP2.animation.curAnim.curFrame==(p>80?1:0),"Psych exactsetterframes");}else{h.playHUD.updateIconsAnimation();ok(h.iconP1.animation.frameIndex==(p<20?1:0)&&h.iconP2.animation.frameIndex==((100-p)*.01<.2?1:0),"NV exactfractionframes");}}var entered=false;if(mode==1)h.psychSourceHealthBar.valueFunction=()->{if(!entered){entered=true;h.health=.25;}return h.health;};else h.nvBar.valueFunction=()->{if(!entered){entered=true;h.health=.25;}return h.health;};var ret=h.set_health(1.25);near(h.health,.25,"reentrant callback currentstore");near(ret,mode==1 ? .25 : 1.25,"source setterreturn dialect");if(mode==1){var first=h.psychSourceHealthBar;var replacement=new PsychSourceBar(0,0,"new",()->h.health,0,4,{image:Paths.image,antialiasing:()->true});var oldPercent=first.percent;first.valueFunction=()->{h.psychSourceHealthBar=replacement;return h.health;};h.health=1;ok(first.percent==oldPercent&&replacement.percent==25,"callback replacement rereads currentbar bounds/commit");}if(mode==1)h.psychSourceHealthBar.valueFunction=()->h.health;else h.nvBar.valueFunction=()->h.health;h.health=7;if(mode==1)h.psychSourceHealthBar.setBounds(4,6);else h.healthBounds.set(4,6);h.updateSourceHealthLimit();near(h.health,6,"actualsource maximum cap");h.health=3;if(mode==1)h.psychSourceHealthBar.setBounds(6,4);else h.healthBounds.set(6,4);h.updateSourceHealthLimit();near(h.health,mode==1?3:4,"reversed capdialect");h.health=3;if(mode==1)h.psychSourceHealthBar.setBounds(4,4);else h.healthBounds.set(4,4);h.updateSourceHealthLimit();near(h.health,3,"equalbounds strictcap");var count=h.syncValues.length;@:bypassAccessor h.health=Math.NaN;h.updateSourceHealthLimit();ok(h.syncValues.length==count&&Math.isNaN(h.health),"NaN no accidentalsetter");if(mode==2){h.healthBounds.set(0,1);h.nvBar.setBounds(0,10);h.health=8.5;h.phases=[];h.nvBar.valueFunction=()->{h.phases.push("value:"+h.health);return h.health;};h.iconP1.frameProbe=v->h.phases.push("icon1");h.iconP2.frameProbe=v->h.phases.push("icon2");h.sampleBar();ok(h.nvBar.percent==85,"precap group sample");h.updateSourceHUDHealthPhase();ok(h.phases.join("|")=="value:8.5|icon1|icon2|timer|value:1","group callback then icons timer cap callback order");near(h.health,1,"statecap afterHUD");ok(h.iconP1.animation.frameIndex==0&&h.iconP2.animation.frameIndex==1&&h.nvBar.percent==10,"icons retainHUDphase whilecap callbackupdatesbar");h.iconP1.updateFrames=false;h.iconP1.animation.frameIndex=1;h.updateSourceHUDHealthPhase();ok(h.iconP1.animation.frameIndex==1,"updateFrames holdsnativeframe independentlyautoUpdate");}}var n=new HealthHost(0);n.health=4;ok(n.health==2&&n.calls==0,"native remainsclamped no sourcework");n.health=-1;ok(n.health==0,"native lowerclamp");var bounds=new FlxBounds<Float>(4);ok(bounds.min==4&&bounds.max==4&&bounds.active,"realbounds optionalmax/defaultactive");ok(bounds.set(2,6)==bounds&&bounds.equals(new FlxBounds<Float>(2,6)),"realbounds methods");}}
'''.replace('__METHODS__',methods).replace('__ICON__',icon)
  with tempfile.TemporaryDirectory(dir=ROOT/'tmp') as tmp:
   work=Path(tmp)
   for name,content in files.items():
    p=work/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content,encoding='utf-8')
   env=os.environ.copy();env['HAXELIB_PATH']=str(ROOT/'.haxelib');env['NEKOPATH']=str(ROOT/'.tools/neko');env['PATH']=str(ROOT/'.tools/haxe')+os.pathsep+str(ROOT/'.tools/neko')+os.pathsep+env.get('PATH','')
   for target in [['--interp'],['-cpp',str(work/'cpp'),'-D','no-compilation']]:
    result=subprocess.run([*HAXE_COMMAND,'-D','flixel','-cp',str(ROOT/'source'),'-cp',tmp,'-main','Main',*target],cwd=ROOT,env=env,capture_output=True,text=True,timeout=40)
    self.assertEqual(result.returncode,0,(result.stdout+result.stderr)[-5000:])
  update=method(ps,'override public function update(elapsed:Float)')
  self.assertLess(update.index('super.update(elapsed);'),update.index('updateSourceHUDHealthPhase(elapsed);'))
  self.assertLess(update.index('updateSourceHUDHealthPhase(elapsed);'),update.index('if (startingSong)'))
  import re
  guards=list(re.finditer(r'if \(([^\n]*)\)\s*(?:\{\s*)?iconP[12]\.iconState =',update))
  self.assertEqual(len(guards),9)
  for match in guards:self.assertIn('sourceNoteTimingMode() == 0',match.group(1))

 def test_actual_iris_psych_bridge_and_lua_property_setters(self):
  ps=(ROOT/'source/PlayState.hx').read_text()
  names=['function set_health(','function bindSourceHealthValues(','function setAllHaxeVar(','function setHaxeVar(','function compatPathTokens(','function compatPathIndex(','function compatReadPathPart(','function compatWritePathPart(','function compatWritePath(target:Dynamic','function compatPropertySeparator(','function compatSetProperty(']
  methods='\n'.join(method(ps,m).replace('function ','public function ',1) for m in names)
  files=bar_fixture_files();actual_bounds(files)
  files['flixel/math/FlxPoint.hx']=files['flixel/math/FlxPoint.hx'].replace('public function new(', 'public static function get(x=0.,y=0.)return new FlxPoint(x,y);public function new(',1)
  files['PsychBaseStageActorGroupCompat.hx']='class PsychBaseStageActorGroupCompat {}'
  files['Main.hx']=r'''import flixel.math.FlxMath;import flixel.util.helpers.FlxBounds;
class PlayState {public static var misses=0;public static var shits=0;public static var bads=0;public static var goods=0;public static var sicks=0;}class Conductor {public static var songPosition:Float=0;}class FlxG {public static var save={data:{botplay:false}};}class GameOverSubstate {public static var instance:Dynamic;}class RuntimeSmokeHarness {public static function enabled()return false;}class EngineCompat {public static function propertyPath(v:Dynamic):String return Std.string(v);public static function legacyCounterName(v:Dynamic):String return "";public static function psychHealthColorArray(a:Dynamic,b:Dynamic,c:Dynamic,d:Dynamic,e:Dynamic,f:Dynamic):Array<Int>return [];}
class HUD {public var notify:Float->Void;public function new(n:Float->Void)notify=n;public function onHealthChange(v:Float):Void notify(v);}
class Host {public var mode:Int;public var sourceHUDIconMode=0;function updatePsychSourceIcons(e:Float):Void{}public var psychSourceIconP1(get,never):Dynamic;function get_psychSourceIconP1():Dynamic return iconP1;public var psychSourceIconP2(get,never):Dynamic;function get_psychSourceIconP2():Dynamic return iconP2;public var health(default,set):Float=1;public var iconsAnimations=true;public var psychSourceHealthBar:PsychSourceBar;public var iconP1={animation:{curAnim:{curFrame:0}}};public var iconP2={animation:{curAnim:{curFrame:0}}};public var boyfriend:Dynamic;public var dad:Dynamic;public var gf:Dynamic;public var playHUD:HUD;public var calls=0;public var observed:Float=0;public var hscriptStates:Map<String,hscript.Interp>=[];public var songSpeed:Float=1;public var useNoteSplashes=true;public var isDead=false;public var psychGlobalProviderFirstSprite:Dynamic;public var camOther:Dynamic;public function new(m:Int){mode=m;psychSourceHealthBar=new PsychSourceBar(0,0,"health",()->{calls++;observed=health;return health;},0,2,{image:Paths.image,antialiasing:()->true});playHUD=new HUD(v->{calls++;observed=health;});}function sourceNoteTimingMode()return mode;function sourceScoreLedgerActive()return mode!=0;function setSourceCpuControlled(v:Bool):Void {}function sourceGameOverMode()return 0;function compatPropertyRoot(name:String):Dynamic return name=="game"?this:Reflect.getProperty(this,name);function sourceHUDBarAlias(n:String):Dynamic return null;function isSourceHUDBarAlias(n:String) return false;function isSourceHUDIconAlias(n:String)return false;function sourceHUDIconAlias(n:String):Dynamic return null;function writeSourceHUDIconAlias(n:String,v:Dynamic):Dynamic return v;function writeSourceHUDBarAlias(n:String,v:Dynamic):Dynamic return v;function compatCoercePropertyValue(t:Dynamic,k:String,v:Dynamic):Dynamic return Std.isOfType(v,String)?Std.parseFloat(v):v;function markPsychGlobalProviderSpritePhase(s:Dynamic,p:String,?d:String):Void {}__METHODS__}
class Main {static function ok(v:Bool,m:String):Void if(!v)throw m;static function near(a:Float,b:Float):Void if(Math.abs(a-b)>.000000001)throw "precision "+a+" "+b;static function main(){for(mode in [1,2]){var host=new Host(mode);var bridge=new SourceIrisBridge(host);bridge.variables.set("game",host);bridge.variables.set("health",99.);host.hscriptStates.set("source",bridge);var legacy=new hscript.Interp();host.hscriptStates.set("legacy",legacy);host.bindSourceHealthValues(bridge.evaluator);bridge.evaluate("health=3.123456789; snapshot=health; game.health=health; again=game.health;", "health-probe.hx");near(host.health,mode==1?3.12346:3.123456789);near(bridge.variables.get("snapshot"),host.health);ok(host.calls==2&&host.observed==host.health,"bare andgame setter/callback order");ok(!bridge.variables.exists("health"),"bulk health sync cannotmask live setter");near(legacy.variables.get("health"),host.health);bridge.evaluate("health=-0.333333333;", "second.hx");near(host.health,mode==1?-.33333:-.333333333);ok(host.calls==3,"subsequentbare assignment remainslive");host.compatSetProperty("health","4.123456789");near(host.health,mode==1?4.12346:4.123456789);ok(host.calls==4&&host.observed==host.health,"actualLua root property setter");host.compatSetProperty("game.health","0.123456789");near(host.health,mode==1?.12346:.123456789);ok(host.calls==5,"actualLua game receiver setter");if(mode==2){bridge.evaluate("import flixel.util.helpers.FlxBounds; bounds=new FlxBounds(4,6); bounds.set(8); active=bounds.active;", "bounds.hx");var bounds:FlxBounds<Float>=cast bridge.variables.get("bounds");ok(Std.isOfType(bounds,FlxBounds)&&bounds.min==8&&bounds.max==8&&bridge.variables.get("active")==true,"actualgenericbounds class/methodimport");}var old=host.playHUD;var replacement=new HUD(v->{host.observed=host.health+10;});host.playHUD=replacement;host.health=.5;if(mode==2)near(host.observed,10.5);else near(host.observed,.5);}}}
'''.replace('__METHODS__',methods).replace('mode==1?.12346:.123456789','mode==1 ? .12346 : .123456789')
  with tempfile.TemporaryDirectory(dir=ROOT/'tmp') as tmp:
   work=Path(tmp)
   for name,content in files.items():
    path=work/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_text(content,encoding='utf-8')
   result=subprocess.run([*HAXE_COMMAND,'-cp',str(ROOT/'source'),'-cp',str(ROOT/'.haxelib/hscript/2,5,0'),'-cp',str(ROOT/'.haxelib/hscript-iris/1,1,3'),'-cp',tmp,'--run','Main'],cwd=ROOT,capture_output=True,text=True,timeout=40)
   self.assertEqual(result.returncode,0,(result.stdout+result.stderr)[-5000:])
